interface PoolEntry {
  transaction: Transaction;
  fee: number;
  arrival: number;
}
type BlockKind = 'BLOCK' | 'UNORPHAN';
const readLines = (name: string) =>
  readFileSync('input/' + name, 'ascii')
    .split('\n')
    .slice(0, -1);
const compareText = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
const referenceOrder = (a: OutputReference, b: OutputReference) =>
  compareText(a.txid, b.txid) || a.index - b.index;
const signed = (value: number) => (value >= 0 ? '+' + value : String(value));
function sum(values: number[]): number {
  let total = 0;
  for (const value of values) total += value;
  return total;
}
function readInput() {
    maxReorg: number('MAXREORG'),
  const lines = readLines('events.txt');
  const events: NodeEvent[] = [];
  for (let i = 0; i < lines.length; i++) {
    const tokens = lines[i].split(' ');
    const time = Number(tokens[0]);
    const kind = tokens[1];
    switch (kind) {
      case 'TX':
        events.push({ time, kind, tokens, transaction: new Transaction(tokens[3]) });
        break;
      case 'BLOCK': {
        const count = Number(tokens[9]);
        events.push({
          time,
          kind,
          tokens,
          block: parseBlock(tokens, lines.slice(i + 1, i + 1 + count)),
        });
        i += count;
        break;
      }
    }
  }
  return { settings, events, wallets: readWallets() };
}
function priorityOrder(a: PoolEntry, b: PoolEntry): number {
  const left = a.fee * b.transaction.size;
  const right = b.fee * a.transaction.size;
  return left === right
    ? compareText(a.transaction.txid, b.transaction.txid)
    : left > right
      ? -1
      : 1;
}
  get nextHeight(): number {
    return this.tip.height + 1;
  }
  message(text: string): void {
    this.log.push(`${this.time} ${text}`);
  }
  refreshMainChain(): void {
    this.mainChain = sequence(this.tip);
    this.mainTransactions.clear();
    for (const block of this.mainChain) {
      for (const transaction of block.transactions) {
        this.mainTransactions.set(transaction.txid, { transaction, height: block.height });
      }
    }
  }
  priority(): PoolEntry[] {
    return this.pool.slice().sort(priorityOrder);
  }
  lockedReferences(): Set<string> {
    const locked = new Set<string>();
    for (const entry of this.pool) {
      for (const input of entry.transaction.inputs) locked.add(input.key);
    }
    return locked;
  }
  acceptable(transaction: Transaction): Acceptance {
    if (transaction.coinbase) return { ok: false, reason: 'coinbase' };
    if (
      this.mainTransactions.has(transaction.txid) ||
      this.pool.some((e) => e.transaction.txid === transaction.txid)
    ) {
      return { ok: false, reason: 'duplicate' };
    }
    const result = check(
      transaction,
      this.tip.utxo,
      new Set(),
      this.nextHeight,
      this.settings.maturity,
      this.owners,
    );
    if (!result.ok) return result;
    const fee = result.fee;
    if (fee * 1000 < this.settings.minFee * transaction.size) {
      return { ok: false, reason: 'low-fee' };
    }
    const references = new Set(transaction.inputs.map((i) => i.key));
    const conflicts = this.pool.filter((e) =>
      e.transaction.inputs.some((i) => references.has(i.key)),
    );
    if (
      conflicts.length &&
      (fee <= sum(conflicts.map((e) => e.fee)) ||
        conflicts.some((e) => fee * e.transaction.size <= e.fee * transaction.size))
    ) {
      return { ok: false, reason: 'conflict' };
    }
    return { ok: true, fee, conflicts };
  }
  recordDrop(transaction: Transaction, reason: string): void {
    this.dropped.set(transaction.txid, reason);
    this.message(`DROP ${short(transaction.txid)} ${reason}`);
  }
  drop(entry: PoolEntry, reason: string): void {
    const index = this.pool.indexOf(entry);
    if (index >= 0) this.pool.splice(index, 1);
    this.recordDrop(entry.transaction, reason);
  }
  register(transaction: Transaction, result: Accepted, arrival: number): void {
    for (const conflict of result.conflicts) this.drop(conflict, 'replaced');
    this.pool.push({ transaction, fee: result.fee, arrival });
    if (this.pool.length > this.settings.maxMempool) {
      const priority = this.priority();
      this.drop(priority[priority.length - 1], 'mempool-full');
    }
  }
  rebuild(returned: Transaction[]): void {
    const previous = this.pool;
    this.pool = [];
    const candidates = [
      ...returned.map((transaction) => ({ transaction, arrival: this.time, returned: true })),
      ...previous.map((entry) => ({
        transaction: entry.transaction,
        arrival: entry.arrival,
        returned: false,
      })),
    ];
    for (const candidate of candidates) {
      if (this.mainTransactions.has(candidate.transaction.txid)) continue;
      const result = this.acceptable(candidate.transaction);
      if (!result.ok) this.recordDrop(candidate.transaction, result.reason);
      else {
        if (candidate.returned) this.message(`RETURN ${short(candidate.transaction.txid)}`);
        this.register(candidate.transaction, result, candidate.arrival);
      }
    }
  }
  switchTip(block: StoredBlock): void {
    const previous = this.tip;
    const fork = forkPoint(previous, block);
    const disconnected = previous.height - fork.height;
    const connected = block.height - fork.height;
    if (disconnected > this.settings.maxReorg) {
      this.message(
        `REFUSE ${block.height} ${short(block.hash)} work ${block.work} fork ${fork.height} depth ${disconnected}`,
      );
      return;
    }
    const returned = this.mainChain
      .filter((b) => b.height > fork.height)
      .flatMap((b) => b.transactions.slice(1));
    this.tip = block;
    this.refreshMainChain();
    if (disconnected === 0) {
      this.message(`TIP ${block.height} ${short(block.hash)} work ${block.work}`);
    } else {
      this.message(
        `REORG ${block.height} ${short(block.hash)} work ${block.work} fork ${fork.height} disconnected ${disconnected} connected ${connected}`,
      );
      this.reorganizations.push({
        time: this.time,
        fork: fork.height,
        disconnected,
        connected,
        old: previous.hash,
        next: block.hash,
      });
    }
    this.rebuild(returned);
  }
  connectBlock(kind: BlockKind, block: Block, peer: Peer): void {
    const parent = this.blocks.get(block.previous)!;
    if (block.height !== parent.height + 1) {
      return this.rejectBlock(kind, block, peer, 'bad-height');
    }
    if (block.difficulty !== requiredDifficulty(parent, this.settings)) {
      return this.rejectBlock(kind, block, peer, 'bad-difficulty');
    }
    if (block.timestamp <= medianTime(parent)) {
      return this.rejectBlock(kind, block, peer, 'time-too-old');
    }
    if (block.timestamp > this.time + this.settings.drift) {
      return this.rejectBlock(kind, block, peer, 'time-too-new');
    }
    const utxo = new Map(parent.utxo);
    const spent = new Set<string>();
    const transactionFees = [0];
    let fees = 0;
    for (let i = 1; i < block.transactions.length; i++) {
      const transaction = block.transactions[i];
      const result = check(
        transaction,
        utxo,
        spent,
        block.height,
        this.settings.maturity,
        this.owners,
      );
      if (!result.ok) return this.rejectBlock(kind, block, peer, `${result.reason} tx ${i + 1}`);
      for (const input of transaction.inputs) spent.add(input.key);
      apply(transaction, utxo, block.height);
      fees += result.fee;
      transactionFees.push(result.fee);
    }
    const cb = block.transactions[0];
    if (cb.outputs.some((o) => !this.owners.has(o.address) || o.amount === 0)) {
      return this.rejectBlock(kind, block, peer, 'bad-output tx 1');
    }
    if (outputTotal(cb) > reward(block.height, this.settings) + fees) {
      return this.rejectBlock(kind, block, peer, 'bad-coinbase');
    }
    apply(cb, utxo, block.height);
    const stored = new StoredBlock(block, parent, utxo, fees, transactionFees, peer.name);
    this.blocks.set(block.hash, stored);
    peer.blocks++;
    this.message(
      `${kind} ${peer.name} ${block.height} ${short(block.hash)} accepted work ${stored.work}`,
    );
    if (stored.work > this.tip.work) this.switchTip(stored);
  }
  resolveOrphans(startingHash: string): void {
    const queue = [startingHash];
    for (let head = 0; head < queue.length; head++) {
      const parentHash = queue[head];
      const children = this.orphans.filter((o) => o.block.previous === parentHash);
      for (const orphan of children) {
        this.orphans.splice(this.orphans.indexOf(orphan), 1);
        const peer = this.peerRecord(orphan.peer);
        if (this.rejected.has(parentHash)) {
          this.rejectBlock('UNORPHAN', orphan.block, peer, 'bad-parent');
        } else this.connectBlock('UNORPHAN', orphan.block, peer);
        queue.push(orphan.block.hash);
      }
    }
  }
  receiveBlock(block: Block, peer: Peer): void {
    if (
      this.blocks.has(block.hash) ||
      this.orphans.some((o) => o.block.hash === block.hash) ||
      this.rejected.has(block.hash)
    ) {
      this.message(`BLOCK ${peer.name} ${block.height} ${short(block.hash)} rejected duplicate`);
      peer.rejectedBlocks++;
      this.tally('block', 'duplicate');
      return;
    }
    const reason =
      contextFreeCheck(block, this.settings.maxBlock) ??
      (this.rejected.has(block.previous) ? 'bad-parent' : null);
    if (reason !== null) {
      this.rejectBlock('BLOCK', block, peer, reason);
      this.resolveOrphans(block.hash);
      return;
    }
    if (!this.blocks.has(block.previous)) {
      this.orphans.push({ block, peer: peer.name });
      peer.orphans++;
      this.message(
        `BLOCK ${peer.name} ${block.height} ${short(block.hash)} orphan parent ${short(block.previous)}`,
      );
      if (this.orphans.length > this.settings.maxOrphans) {
        this.message(`EVICT ${short(this.orphans.shift()!.block.hash)} orphan-limit`);
      }
      return;
    }
    this.connectBlock('BLOCK', block, peer);
    this.resolveOrphans(block.hash);
  }
  processEvents(): void {
    for (const event of this.events) {
      this.time = event.time;
      for (const entry of this.pool.slice()) {
        if (this.time - entry.arrival >= this.settings.expiry) this.drop(entry, 'expired');
      }
      if (event.kind === 'TX' || event.kind === 'BLOCK') {
        const peer = this.peerRecord(event.tokens[2]);
        if (peer.score >= this.settings.banThreshold) {
          peer.ignored++;
          this.message(`IGNORE ${peer.name} ${event.kind}`);
          continue;
        }
        if (event.kind === 'TX') this.receiveTransaction(event.transaction, peer);
        else this.receiveBlock(event.block, peer);
        continue;
      }
  chainLines(): string[] {
    const lines = [
      `TIP ${this.tip.height} ${this.tip.hash} work ${this.tip.work} stored ${this.blocks.size} orphans ${this.orphans.length}`,
    ];
    for (const block of this.mainChain) {
      const miner =
        block.height === 0 ? '-' : this.owners.get(block.transactions[0].outputs[0].address)!.name;
      lines.push(
        `BLOCK ${block.height} ${block.hash} prev ${short(block.previous)} time ${block.timestamp} bits ${block.difficulty} nonce ${block.nonce} txs ${block.transactions.length} size ${block.size} fees ${block.fees} miner ${miner} source ${block.source} work ${block.work}`,
      );
    }
    const mainHashes = new Set(this.mainChain.map((b) => b.hash));
    const stale = [...this.blocks.values()]
      .filter((b) => !mainHashes.has(b.hash))
      .sort((a, b) => a.height - b.height || compareText(a.hash, b.hash));
    for (const b of stale) {
      lines.push(
        `STALE ${b.height} ${b.hash} prev ${short(b.previous)} source ${b.source} work ${b.work}`,
      );
    }
    for (const r of this.reorganizations) {
      lines.push(
        `REORG ${r.time} fork ${r.fork} disconnected ${r.disconnected} connected ${r.connected} old ${short(r.old)} new ${short(r.next)}`,
      );
    }
    this.priority().forEach((e, i) =>
      lines.push(
        `MEMPOOL ${i + 1} ${e.transaction.txid} fee ${e.fee} size ${e.transaction.size} time ${e.arrival}`,
      ),
    );
    return lines;
  }
  balanceLines(): string[] {
    const lines = ['wallet,address,balance,immature,locked,incoming,utxos'];
    const locked = this.lockedReferences();
    for (const wallet of this.wallets) {
      const coins = [...this.tip.utxo.values()].filter((c) => c.address === wallet.address);
      const balance = sum(coins.map((c) => c.amount));
      const immature = sum(
        coins
          .filter((c) => !mature(c, this.nextHeight, this.settings.maturity))
          .map((c) => c.amount),
      );
      const reserved = sum(
        coins.filter((c) => locked.has(`${c.txid}:${c.index}`)).map((c) => c.amount),
      );
      let incoming = 0;
      for (const entry of this.pool) {
        for (const output of entry.transaction.outputs) {
          if (output.address === wallet.address) incoming += output.amount;
        }
      }
      lines.push(
        [wallet.name, wallet.address, balance, immature, reserved, incoming, coins.length].join(
          ',',
        ),
      );
    }
    return lines;
  }
  utxoLines(): string[] {
    const locked = this.lockedReferences();
    const coins = [...this.tip.utxo.values()].sort(referenceOrder);
    const lines = coins.map((c) => {
      const reference = `${c.txid}:${c.index}`;
      const category = c.height === 0 ? 'genesis' : c.coinbase ? 'coinbase' : 'payment';
      const state = !mature(c, this.nextHeight, this.settings.maturity)
        ? 'immature'
        : locked.has(reference)
          ? 'locked'
          : 'free';
      return `${reference} ${this.owners.get(c.address)!.name} ${c.amount} height ${c.height} ${category} ${state}`;
    });
    const root = merkle(lines.map(hash));
    lines.push(`TOTAL ${coins.length} ${sum(coins.map((c) => c.amount))}`, 'ROOT ' + root);
    return lines;
  }
  historyLines(): string[] {
    const lines: string[] = [];
    const priority = this.priority();
    for (const wallet of this.wallets) {
      lines.push(`WALLET ${wallet.name} ${wallet.address}`);
      let count = 0;
      let totalSpent = 0;
      let totalReceived = 0;
      let balance = 0;
      for (const block of this.mainChain) {
        for (const transaction of block.transactions) {
          let spent = 0;
          for (const input of transaction.inputs) {
            const output = this.mainTransactions.get(input.txid)!.transaction.outputs[input.index];
            if (output.address === wallet.address) spent += output.amount;
          }
          const received = sum(
            transaction.outputs.filter((o) => o.address === wallet.address).map((o) => o.amount),
          );
          if (spent === 0 && received === 0) continue;
          const net = received - spent;
          balance += net;
          count++;
          totalSpent += spent;
          totalReceived += received;
          const category =
            block.height === 0 ? 'genesis' : transaction.coinbase ? 'coinbase' : 'payment';
          lines.push(
            `${block.height} ${short(transaction.txid)} ${category} spent ${spent} received ${received} net ${signed(net)} balance ${balance}`,
          );
        }
      }
      let pending = 0;
      for (const entry of priority) {
        let spent = 0;
        for (const input of entry.transaction.inputs) {
          const coin = this.tip.utxo.get(input.key)!;
          if (coin.address === wallet.address) spent += coin.amount;
        }
        const received = sum(
          entry.transaction.outputs
            .filter((o) => o.address === wallet.address)
            .map((o) => o.amount),
        );
        if (spent === 0 && received === 0) continue;
        pending++;
        lines.push(
          `pending ${short(entry.transaction.txid)} spent ${spent} received ${received} net ${signed(received - spent)}`,
        );
      }
      lines.push(
        `END ${wallet.name} txs ${count} spent ${totalSpent} received ${totalReceived} balance ${balance} pending ${pending}`,
      );
    }
    return lines;
  }
